'use client';

import { useQuery } from '@tanstack/react-query';
import { ArrowUpRight, ArrowDownLeft, Flame, Coins } from 'lucide-react';
import { useState } from 'react';

export default function TransactionsTable({ limit = 10 }: { limit?: number }) {
  const [page, setPage] = useState(0);

  const { data, isLoading } = useQuery({
    queryKey: ['ksc-transactions', page, limit],
    queryFn: async () => {
      const res = await fetch(
        `http://localhost:4000/api/tokens/transactions?limit=${limit}&offset=${page * limit}`
      );
      return res.json();
    },
    refetchInterval: 15000, // Refresh every 15 seconds
  });

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'mint':
        return <Coins className="w-4 h-4 text-green-600" />;
      case 'burn':
        return <Flame className="w-4 h-4 text-red-600" />;
      case 'transfer':
        return <ArrowUpRight className="w-4 h-4 text-blue-600" />;
      default:
        return null;
    }
  };

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'mint':
        return 'bg-green-100 text-green-800';
      case 'burn':
        return 'bg-red-100 text-red-800';
      case 'transfer':
        return 'bg-blue-100 text-blue-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const formatTime = (timestamp: string) => {
    return new Date(timestamp).toLocaleString('ru-RU', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  if (isLoading) {
    return (
      <div className="bg-white rounded-lg border border-gray-200 p-6 animate-pulse">
        <div className="h-8 bg-gray-200 rounded w-1/3 mb-4"></div>
        <div className="space-y-3">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="h-16 bg-gray-200 rounded"></div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg border border-gray-200 overflow-hidden">
      <div className="px-6 py-4 border-b border-gray-200 flex items-center justify-between">
        <h3 className="text-lg font-semibold text-gray-900">
          Recent Transactions / Последние транзакции
        </h3>
        <div className="text-sm text-gray-500">
          Total: {data?.total || 0} transactions
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Type / Тип
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                From / От
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                To / Кому
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Amount / Сумма
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Time / Время
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {data?.transactions?.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-8 text-center text-gray-500">
                  No transactions yet / Транзакций пока нет
                </td>
              </tr>
            ) : (
              data?.transactions?.map((tx: any) => (
                <tr key={tx.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center gap-2">
                      {getTypeIcon(tx.type)}
                      <span
                        className={`px-2 py-1 text-xs font-medium rounded-full ${getTypeColor(tx.type)}`}
                      >
                        {tx.type}
                      </span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="text-sm font-medium text-gray-900">
                      {tx.fromName}
                    </div>
                    {tx.from !== 'Contract' && (
                      <div className="text-xs text-gray-500 font-mono">
                        {tx.from.slice(0, 6)}...{tx.from.slice(-4)}
                      </div>
                    )}
                  </td>
                  <td className="px-6 py-4">
                    <div className="text-sm font-medium text-gray-900">
                      {tx.toName}
                    </div>
                    {tx.to !== 'Contract' && (
                      <div className="text-xs text-gray-500 font-mono">
                        {tx.to.slice(0, 6)}...{tx.to.slice(-4)}
                      </div>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="text-sm font-semibold text-gray-900">
                      {tx.value} KSC
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {formatTime(tx.created)}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {data?.hasMore && (
        <div className="px-6 py-4 border-t border-gray-200 flex items-center justify-between">
          <button
            onClick={() => setPage(Math.max(0, page - 1))}
            disabled={page === 0}
            className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            ← Previous
          </button>
          <div className="text-sm text-gray-600">
            Page {page + 1} of {Math.ceil((data?.total || 0) / limit)}
          </div>
          <button
            onClick={() => setPage(page + 1)}
            disabled={!data?.hasMore}
            className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Next →
          </button>
        </div>
      )}
    </div>
  );
}

